            <div class="pixel-water"><span>✧</span><span>≈≈≈≈≈≈≈≈≈≈≈≈≈≈≈</span></div>
            <nav class="map-rooms" aria-label="地点快捷入口"><button v-for="(room,index) in [{icon:'▣',name:'工作室',action:'builder'},{icon:'▤',name:'档案室',action:'files'},{icon:'⌂',name:'角色屋',action:'files'},{icon:'▥',name:'剧场',action:'files'},{icon:'▧',name:'绘图间',action:'builder'},{icon:'▣',name:'会客厅',action:'files'}]" :key="room.name" type="button" @click="room.action==='builder'?openBuilder():view='files'"><i :class="`room-icon room-${index}`">{{room.icon}}</i><span>{{room.name}}</span></button></nav>
            <article class="pocket-message"><div class="message-avatar"><img v-if="characters[0]?.avatar" :src="characters[0].avatar" alt=""/><CharacterIcon v-else/></div><div><p>{{ characters[0]?.details || '明天也会有新的故事。去绘图室创造一位角色，或到档案室看看已经遇见的朋友吧。' }}</p><small>《 {{ characters[0]?.name || '掌机日记' }} · 刚刚</small></div><i class="message-pin">●</i></article>
          </div>
          <div class="screen-caption">♡ MIAO-LCD · 本喵的小天地 ♡</div>
        </div>
      </main>
      <footer class="pocket-controls"><button class="dpad" type="button" aria-label="打开地图档案" @click="view='files'"><i>✦</i></button><div class="control-center"><button type="button" aria-label="绘图室" @click="openBuilder">▧</button><button type="button" aria-label="角色档案" @click="view='files'">◎</button><button type="button" aria-label="新建角色" @click="openBuilder">♧</button><button type="button" aria-label="浏览角色" @click="view='files'">▤</button></div><button class="pocket-add" type="button" aria-label="新建角色" @click="openBuilder">＋</button></footer>
