.pixel-world{position:relative;flex:1;min-height:0;overflow:hidden;background-color:#fcf5fb;background-image:radial-gradient(#d9c3e355 1px,transparent 1.4px),linear-gradient(180deg,#fff9fd 0%,#fbf4fb 68%,#d6effa 68%,#c4e6f5 100%);background-size:6px 6px,100% 100%}.pixel-world:before{position:absolute;right:0;bottom:27%;left:0;height:3px;content:"";background:#fff;box-shadow:0 4px 0 #b7deef,0 9px 0 #d0ebf6}.world-path{position:absolute;inset:8% 5% 22%;width:90%;height:70%;overflow:visible}.world-path path{fill:none;stroke:#b19aca;stroke-width:3;stroke-dasharray:3 8;stroke-linecap:square;opacity:.78}.pixel-cloud{position:absolute;color:#fff;font-size:40px;text-shadow:8px 5px #f3d8e9;opacity:.9}.cloud-one{top:5%;left:8%}.cloud-two{top:9%;right:9%;font-size:31px}.pixel-star{position:absolute;color:#d975a1;font-style:normal;font-size:18px;text-shadow:2px 2px #f9d4e4}.star-one{top:8%;left:35%}.star-two{top:29%;right:8%;color:#9e8ac7}.star-three{top:53%;left:50%;color:#94c9e2}.map-place{position:absolute;z-index:2;display:flex;flex-direction:column;align-items:center;gap:3px;padding:4px;border:0;background:transparent;color:#514767;font:inherit;cursor:pointer;filter:drop-shadow(2px 3px 0 #8d7ab540);transition:transform .15s steps(2,end)}.map-place:active{transform:translateY(-4px) scale(1.08)}.map-place strong{font-size:11px;font-weight:1000;text-shadow:1px 1px #fff}.map-place small{color:#90849d;font-size:8px}.place-home{top:12%;left:7%}.place-tower{top:7%;left:48%}.place-cafe{top:27%;right:8%}.place-studio{top:41%;left:39%}.place-library{top:57%;left:8%}.pixel-house{width:78px;height:55px;position:relative;display:block;border:4px solid #7c69a5;background:#fff0fa;box-shadow:inset 0 -9px #e9c6df}.pixel-house:before{position:absolute;top:-23px;left:-8px;width:78px;height:25px;content:"";border:4px solid #7c69a5;background:#f5bed6;clip-path:polygon(50% 0,100% 100%,0 100%);filter:drop-shadow(0 3px #fff)}.pixel-house:after{position:absolute;right:8px;bottom:0;width:15px;heigh